def rows(aid):
 a=assets[aid]; return [dict(zip([c['name'] for c in a['columns']],r)) for r in a['rows']]
def table(rs,cols):
 return '\n'.join([' | '.join(cols)]+[' | '.join(str(r[c]) for c in cols) for r in rs])
def fence(s,lang='python'):return '```'+lang+'\n'+s.strip()+'\n```'
