cases(cid,'Read the conversion and fixture-review excerpts. Decide whether each meets its stated shape, dtype, pairing and assertion criterion. The source fixtures have matching observation order; feature dtype is float32 and target dtype is long. Execution is ordinary non-optimized.',[
 case('Conversion used for the valid (4, 2)/(4,) pair and the one-observation (1, 2)/(1,) boundary:\n'+fence(base)+'\nReview: callers assert returned feature/target shapes and separate dtypes. They require AssertionError for three targets and for either incompatible declared shape; conversion keeps source row order.',True,'Both arrays receive separate declared dtypes, shape checks precede tuple return and the common batch length is asserted; the stated callers cover accepted, boundary and incompatible fixtures.'),
 case('Same function, but the target conversion is replaced by:\n'+fence('targets = torch.from_numpy(targets_array).to(dtype=feature_dtype)')+'\nDeclared target dtype remains long.',False,'The feature dtype is not the separately declared target dtype.'),
 case('Same source-order fixtures; replacement acceptance gate:\n'+fence('assert features.shape == (4, 2)\nreturn features, targets')+'\nNo target or common-batch assertion is present; the three-target fixture is marked accepted.',False,'The three-target fixture violates target shape and common batch length; checking features alone cannot reject it.'),
 case('The caller swaps target observation order before conversion, while preserving its (4,) shape and long dtype; it declares alignment based only on shape.',False,'Correct shape and dtype do not prove correspondence after targets alone are reordered.')])
cases('mle.dataset_minibatch_loader','Read the dataset/loader reviews for five observations whose feature and target both encode the observation identity. Decide whether each pairing or batch-boundary check is valid. An incorrect pairing must fail assert in ordinary non-optimized execution.',[
 case(fence('from torch.utils.data import Dataset, DataLoader\nclass Paired(Dataset):\n    def __len__(self): return len(features)\n    def __getitem__(self, index): return features[index], targets[index]\nfeatures = [0, 1, 2, 3, 4]\ntargets = [0, 1, 2, 3, 4]\ndataset = Paired()\nassert len(dataset) == 5\nfor i in range(5):\n    assert dataset[i] == (features[i], targets[i])\nfor drop, expected in [(False, [2, 2, 1]), (True, [2, 2])]:\n    batches = list(DataLoader(dataset, batch_size=2, shuffle=False, drop_last=drop))\n    assert [len(x) for x, y in batches] == expected\n    for x, y in batches: assert (x == y).all()\nfor x, y in DataLoader(dataset, batch_size=2, shuffle=True):\n    assert (x == y).all()')+'\nFailure test supplies one deliberately mismatched target and expects the same pairing assert to raise AssertionError.',True,'Same-index tuple retrieval preserves identity, explicit drop_last checks cover both final-batch policies and shuffled checks do not assume source order.'),
 case(fence('def __getitem__(self, index):\n    return features[index], targets[(index + 1) % len(targets)]'),False,'The target comes from a different observation index.'),
 case('Five observations, batch_size=2, shuffle=False, drop_last=False; the review asserts batch lengths [2, 2] and marks the retained final batch a defect.',False,'Retaining the incomplete batch requires lengths [2, 2, 1].'),
 case('shuffle=True; the only pairing test requires the first feature identity to be zero.',False,'Source order is not guaranteed under shuffle, and checking one identity does not verify its paired target.')])
cases('mle.neural_model_definition','Read these module excerpts for two input features and one unconstrained output per observation. Judge module registration, intermediate dimensions, activation placement and the (4, 1) fixture contract.',[
 case(fence('import torch.nn as nn\nclass Model(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.layers = nn.Sequential(nn.Linear(2, 8), nn.ReLU(), nn.Linear(8, 1))\n    def forward(self, x):\n        return self.layers(x)\ndef make_model(): return Model()\nmodel = make_model()\nassert model(fixture_features).shape == (4, 1)'),True,'The registered composition has matching widths, an intermediate ReLU and an unconstrained one-wide final linear output.'),
 case(fence('self.layers = nn.Sequential(nn.Linear(2, 8), nn.ReLU(), nn.Linear(4, 1))'),False,'The first layer produces width eight while the next linear layer expects four.'),
 case(fence('self.layers = nn.Sequential(nn.Linear(2, 8), nn.ReLU(), nn.Linear(8, 1), nn.ReLU())'),False,'A final ReLU constrains the supplied unconstrained numerical output.'),
 case('The class defines self.layers in __init__ but has no forward method, and the review calls it a complete module implementation.',False,'The intended module requires an implemented forward method as well as registered layer attributes.')])
cases('mle.autograd_gradients','Read the gradient-verification excerpts. Decide whether they verify fresh leaf gradients against the matrix chain rule. D already includes the supplied loss reduction; tolerances are declared. Failure assertions run in ordinary non-optimized execution.',[
 case(fence(codes['mle.autograd_gradients'])+'\nBoundary checks use zero D and require zero references of the same shapes. A failure test asserts allclose against differing_reference and expects AssertionError.',True,'Fresh gradients are compared with X.T @ D and D summed over rows under explicit tolerances; the same predicates cover a zero-derivative boundary and a mismatched reference.'),
 case(fence('weight_reference = (X.T @ D) / X.shape[0]')+'\nD already includes the reduction.',False,'Dividing again changes the required reference.'),
 case('The same scalar loss is backpropagated after a fresh graph is formed, but W.grad and b.grad from the preceding computation are not cleared before comparison.',False,'Backward accumulates gradients; the comparison is no longer of the fresh computation alone.'),
 case(fence('assert W.grad.shape == weight_reference.shape')+'\nThis is the only numerical-agreement check.',False,'Matching shape does not test values against the declared tolerances.')])
