cases('ml.task_specific_pretrained_weight_fine_tuning','Read the classifier-only ViT adaptation and comparison excerpts. Decide whether each satisfies its stated adaptation, gradient, matched-validation or leakage criterion.\n'+cost_context,[
 case(fence('import torch\nfrom torch import nn\nfrom transformers import AutoImageProcessor, ViTForImageClassification, TrainingArguments, Trainer\nmodel = ViTForImageClassification.from_pretrained(checkpoint)\noriginal_mapping = dict(model.config.id2label)\nprocessor = AutoImageProcessor.from_pretrained(checkpoint)\n# Retain frozen pretrained outputs with original_mapping on validation_images.\nfor parameter in model.parameters(): parameter.requires_grad = False\nmodel.classifier = nn.Linear(model.config.hidden_size, num_labels)\nmodel.num_labels = model.config.num_labels = num_labels\nmodel.config.id2label = id2label\nmodel.config.label2id = label2id\nargs = TrainingArguments(output_dir=output_dir, num_train_epochs=epochs, per_device_train_batch_size=batch_size, learning_rate=learning_rate, eval_strategy="epoch", remove_unused_columns=False)\ntrainer = Trainer(model=model, args=args, train_dataset=train_dataset, eval_dataset=validation_dataset, data_collator=data_collator, processing_class=processor)\ntrainer.train()')+'\nReview evidence: checkpoint processor supplies pixel_values for train and validation images; original reference mapping remains distinct from the two-class task mapping. Snapshot comparisons show changed head values and identical frozen backbone values. In-run logits are (4, 2); long targets are (4,) with indices 0 or 1. The selected loss is backpropagated after clearing old gradients. Head-gradient comparison expresses the head as Z = XW + b, where W is classifier.weight.T; the inspected gradient is classifier.weight.grad.T. It uses X.T @ D, D already contains reduction; X='+json.dumps(X)+', D='+json.dumps(D)+', reference='+json.dumps(grad_ref)+'. Computed selected gradient agrees at declared rtol/atol. Same-cohort validation rates and costs follow the supplied table, adapted cost is lower under the stated rule; no protected-test data is accessed. An empty actual-negative group returns undefined FPR ('+str(empty_rate)+'), not zero.',True,'The excerpt preserves the pretrained reference and processor, freezes only existing parameters before making a trainable task head, verifies shapes/gradient and changed head versus unchanged backbone, and compares conditional costs on matched validation with undefined-rate handling.'),
 case('All parameters are frozen after replacing the classifier, including the new head; the review claims classifier-only supervised adaptation succeeded without checking changed head weights.',False,'The new classifier must receive supervised updates and show changed values; freezing it contradicts that criterion.'),
 case('The selected head-gradient reference divides X.T @ D by the minibatch size again although D already includes the loss reduction.',False,'Reduction is already in D; another division produces the wrong chain-rule reference.'),
 case('The pretrained reference uses one validation cohort and the adapted head uses a different cohort; the review attributes their cost difference solely to adaptation.',False,'The comparison requires the same validation observations for both prediction sets.'),
 case('Rate review for the adapted counts in the table: FPR is reported as FP/(FP+TP) = '+str(counts[1]['FP']/(counts[1]['FP']+counts[1]['TP']))+'.',False,'FPR conditions on actual negatives and uses FP+TN, not predicted-positive counts FP+TP.'),
 case('Cost review replaces the supplied deployment probabilities and unequal error costs with an unweighted average of FPR and FNR, reporting adapted cost '+str((counts[1]['FPR']+counts[1]['FNR'])/2)+'.',False,'The supplied expected-cost contract weights each conditional rate by its deployment class probability and corresponding error cost; an unweighted average is not that cost.'),
 case('A cohort has no actual negatives, and the returned report defines FPR=0 rather than marking it undefined.',False,'FP+TN is zero, so the conditional false-positive rate is undefined.'),
 case('Protected test images are used to tune epochs and choose the lower-cost checkpoint.',False,'Using protected test observations for settings or model choice leaks information into the chosen system.')])

